//! What agents send: MCP JSON-RPC 2.0 lines (`--mcp`), with the tools it lists, and JSON CLI lines.

use super::Session;
use cuprita_core::json::{Val, json_str, list};

impl Session {
    pub fn cli_line(&mut self, line: &str) -> String {
        let mut run = || {
            let v = Val::parse(line).ok_or_else(|| "bad json".to_string())?;
            let cmd = v.str("cmd").ok_or_else(|| "missing cmd".to_string())?;
            self.exec(cmd, &v)
        };
        run().unwrap_or_else(|e| format!(r#"{{"error":{}}}"#, json_str(&e)))
    }

    pub fn mcp_line(&mut self, line: &str) -> Option<String> {
        if line.trim().is_empty() {
            return None;
        }
        let Some(req) = Val::parse(line) else {
            return Some(r#"{"jsonrpc":"2.0","id":null,"error":{"code":-32700,"message":"parse error"}}"#.into());
        };
        let id = req.get("id")?.to_json();
        let params = req.get("params").unwrap_or(&Val::Null);
        let res = match req.str("method").unwrap_or("") {
            "initialize" => {
                let ver = params.str("protocolVersion").unwrap_or("2024-11-05");
                format!(
                    r#"{{"protocolVersion":{},"capabilities":{{"tools":{{}}}},"serverInfo":{{"name":"cuprita","version":"0.0.1"}}}}"#,
                    json_str(ver)
                )
            }
            "ping" => "{}".into(),
            // One message a line, as MCP's stdio transport reads them: the list is kept a tool a line.
            "tools/list" => TOOLS.replace('\n', ""),
            "tools/call" => {
                let name = params.str("name").unwrap_or("");
                let args = params.get("arguments").unwrap_or(&Val::Null);
                match self.exec(name, args) {
                    Ok(t) => format!(r#"{{"content":[{{"type":"text","text":{}}}]}}"#, json_str(&t)),
                    Err(e) => format!(r#"{{"content":[{{"type":"text","text":{}}}],"isError":true}}"#, json_str(&e)),
                }
            }
            _ => return Some(format!(r#"{{"jsonrpc":"2.0","id":{id},"error":{{"code":-32601,"message":"method not found"}}}}"#)),
        };
        Some(format!(r#"{{"jsonrpc":"2.0","id":{id},"result":{res}}}"#))
    }
}

/// Each tool's name, as `--help` lists them.
pub(crate) fn names() -> Vec<String> {
    let tools = Val::parse(TOOLS).expect("TOOLS is JSON");
    tools.arr("tools").unwrap_or_default().iter().filter_map(|t| t.str("name").map(String::from)).collect()
}

/// The tools `names` as Ollama's functions (`cuprita_core::ollama`): the chat's.
pub(crate) fn functions(names: &[&str]) -> String {
    let tools = Val::parse(TOOLS).expect("TOOLS is JSON");
    let picked = tools.arr("tools").unwrap_or_default().iter().filter(|t| t.str("name").is_some_and(|n| names.contains(&n)));
    list(picked.map(|t| {
        let json = |k| t.get(k).map_or_else(|| "null".into(), Val::to_json);
        format!(
            r#"{{"type":"function","function":{{"name":{},"description":{},"parameters":{}}}}}"#,
            json("name"),
            json("description"),
            json("inputSchema")
        )
    }))
}

